def to_dict(self):
    "Get a :class:`dict` copy of the Callpoint. Useful for serialization."
    ret = {}
    for slot in self.__slots__:
        try:
            val = getattr(self, slot)
        except AttributeError:
            pass
        else:
            ret[slot] = str(val) if isinstance(val, _DeferredLine) else val
    return ret

