def insert(self, data):
    """
    For inserting the data in the Tree
    """
    if self.data == data:
        # As BST cannot contain duplicate data
        return False

    elif data < self.data:
        # Data less than the root data is placed to the left of the root
        if self.left_child:
            return self.left_child.insert(data)
        else:
            self.left_child = BSTNode(data)
            return True

    else:
        # Data greater than the root data is placed to the right of the root
        if self.right_child:
            return self.right_child.insert(data)
        else:
            self.right_child = BSTNode(data)
            return True

def find(self, data):
    """
    This function checks whether the specified data is in tree or not
    """
    if data == self.data:
        return True
    elif data < self.data:
        if self.left_child:
            return self.left_child.find(data)
        else:
            return False
    else:
        if self.right_child:
            return self.right_child.find(data)
        else:
            return False

