def kmp_search(text, pattern):
    """
    Find all occurrences of pattern in text using KMP algorithm

    :param text: string to search in
    :param pattern: string pattern to search for
    :return: list of starting indices where pattern is found
    """
    if not text or not pattern:
        return []

    if len(pattern) > len(text):
        return []

    # Build failure function (LPS array)
    lps = build_lps_array(pattern)

    matches = []
    i = 0  # index for text
    j = 0  # index for pattern

    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == len(pattern):
            matches.append(i - j)
            j = lps[j - 1]
        elif i < len(text) and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return matches

def kmp_search_first(text, pattern):
    """
    Find the first occurrence of pattern in text using KMP algorithm

    :param text: string to search in
    :param pattern: string pattern to search for
    :return: index of first occurrence or -1 if not found
    """
    if not text or not pattern:
        return -1

    if len(pattern) > len(text):
        return -1

    lps = build_lps_array(pattern)

    i = 0  # index for text
    j = 0  # index for pattern

    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == len(pattern):
            return i - j
        elif i < len(text) and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return -1

def kmp_search_overlapping(text, pattern):
    """
    Find all occurrences including overlapping ones

    :param text: string to search in
    :param pattern: string pattern to search for
    :return: list of starting indices where pattern is found
    """
    if not text or not pattern:
        return []

    if len(pattern) > len(text):
        return []

    lps = build_lps_array(pattern)
    matches = []
    i = 0  # index for text
    j = 0  # index for pattern

    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == len(pattern):
            matches.append(i - j)
            # For overlapping matches, use LPS to find next possible match
            j = lps[j - 1]
        elif i < len(text) and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return matches

