def binary_search(_list, left, right, target):
    if right >= left:
        mid = (left + right) // 2

        # if element is present at the mid itself
        if _list[mid] == target:
            return mid

        # If the element is smaller than mid, then it
        # can only be present in the left subarray
        if _list[mid] > target:
            return binary_search(_list, left, mid - 1, target)

        # Else the element can only be present in the right
        return binary_search(_list, mid + 1, right, target)

    return False

def select(array, left, right, n):
    """
    helper method for search function

    :param array:
    :param left:
    :param right:
    :param n:
    :return:
    """
    if left == right:
        return array[left]
    split = partition(array, left, right, n)
    length = split - left + 1
    if length == n:
        return array[split]
    elif n < length:
        return select(array, left, split - 1, n)
    else:
        return select(array, split + 1, right, n - length)

def search(_list, left, right, target):
    if right >= left:
        mid1 = (left + right) // 3
        mid2 = (mid1 + right) // 3

        # if target is present at mid1
        if _list[mid1] == target:
            return mid1

        # if target is present at mid2
        if _list[mid2] == target:
            return mid2

        # if target is present at left one-third
        if _list[mid1] > target:
            return search(_list, left, mid1 - 1, target)

        # if target is present at right one-third
        if _list[mid2] < target:
            return search(_list, mid2 + 1, right, target)

        # if target is present in the middle one-third
        return search(_list, mid1 + 1, mid2 - 1, target)

    return False

