def solve_n_queens_first_solution(n):
    """
    Find the first solution to N-Queens problem

    :param n: size of the chessboard (n x n)
    :return: first solution found or None if no solution exists
    """
    if n <= 0:
        return None

    board = [-1] * n

    def is_safe(row, col):
        for i in range(row):
            if board[i] == col or \
               board[i] - i == col - row or \
               board[i] + i == col + row:
                return False
        return True

    def backtrack(row):
        if row == n:
            return True

        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board[:]
    return None

