        current_number = _list[i]
        for j in range(i - 1, -1, -1):
            if _list[j] > current_number:
                _list[j], _list[j + 1] = _list[j + 1], _list[j]
            else:
                _list[j + 1] = current_number
                break
    return _list

def gnome_sort(arr):
    '''
    Gnome Sort also called Stupid sort is based on the concept of a Garden Gnome sorting his flower pots.
    A garden gnome sorts the flower pots by the following method-

    He looks at the flower pot next to him and the previous one;
    if they are in the right order he steps one pot forward, otherwise he swaps them and steps one pot backwards.
    If there is no previous pot (he is at the starting of the pot line), he steps forwards;
    if there is no pot next to him (he is at the end of the pot line), he is done.

    This is an in-place sort.

    :param arr: the array of values to sort
    :return: the sorted array, which is the same reference as arr
    '''
    index = 0
    while index < len(arr):
        if index == 0:
            index = index + 1
        elif arr[index] >= arr[index - 1]:
            index = index + 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index = index - 1

    return arr

def sort(_list):
    """
    Bubble Sorting algorithm

    :param _list: list of values to sort
    :return: sorted values
    """
    for i in range(len(_list)):
        for j in range(len(_list) - 1, i, -1):
            if _list[j] < _list[j - 1]:
                _list[j], _list[j - 1] = _list[j - 1], _list[j]
    return _list

def improved_sort(_list):
    """
    Improved Bubble Sorting algorithm

    :param _list: list of values to sort
    :return: sorted values
    """
    for i in range(len(_list)):
        stop = True
        for j in range(len(_list) - 1, i, -1):
            if _list[j] < _list[j - 1]:
                stop = False
                _list[j], _list[j - 1] = _list[j - 1], _list[j]
        if stop:
            return _list
    return _list

def brick_sort(arr):
    """Performs an odd-even in-place sort, which is a variation of a bubble
    sort.

    https://www.geeksforgeeks.org/odd-even-sort-brick-sort/

    :param arr: the array of values to sort
    :return: the sorted array
    """
    # Initially array is unsorted
    is_sorted = False
    while not is_sorted:
        is_sorted = True

        for i in range(1, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                is_sorted = False

        for i in range(0, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                is_sorted = False

    return arr

def inplace_insertion_sort(arr, start_ind, end_ind):
    """
    Performs an in-place insertion sort over a continuous slice of an
    array. A natural way to avoid this would be to use numpy arrays,
    where slicing does not copy.

    This is in-place and has no result.

    :param arr: the array to sort
    :param start_ind: the index to begin sorting at
    :param end_ind: the index to end sorting at. This index is excluded
        from the sort (i.e., len(arr) is ok)
    """
    for i in range(start_ind + 1, end_ind):
        current_number = arr[i]

        for j in range(i - 1, start_ind - 1, -1):
            if arr[j] > current_number:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
            else:
                arr[j + 1] = current_number
                break

def sort(_list):
    """
    selection sort algorithm

    :param _list: list of integers to sort
    :return: sorted list
    """

    # For iterating n - 1 times
    for i in range(len(_list) - 1):
        minimum = i

        # Compare i and i + 1 element
        for j in range(i + 1, len(_list)):
            if _list[j] < _list[minimum]:
                minimum = j
        if minimum != i:
            _list[i], _list[minimum] = _list[minimum], _list[i]
    return _list

def sort(_list, base=10):
    """
    Radix Sort

    :param _list: array to sort
    :param base: base radix number
    :return: sorted list
    """
    # TODO: comment this

    result_list = []
    power = 0
    while _list:
        bs = [[] for _ in range(base)]
        for x in _list:
            bs[x // base ** power % base].append(x)
        _list = []
        for b in bs:
            for x in b:
                if x < base ** (power + 1):
                    result_list.append(x)
                else:
                    _list.append(x)
        power += 1
    return result_list

def sort(_list):
    """
    counting sort algorithm

    :param _list: list of values to sort
    :return: sorted values
    """
    try:
        max_value = 0
        for i in range(len(_list)):
            if _list[i] > max_value:
                max_value = _list[i]

        buckets = [0] * (max_value + 1)

        for i in _list:
            buckets[i] += 1
        i = 0

        for j in range(max_value + 1):
            for a in range(buckets[j]):
                _list[i] = j
                i += 1

        return _list

    except TypeError as error:
        print('Counting Sort can only be applied to integers. {}'.format(error))

def shift_down(_list, start, end):
    root = start
    while root * 2 + 1 <= end:
        child = root * 2 + 1
        # right child exists and is greater than left child
        if child + 1 <= end and _list[child] < _list[child + 1]:
            child += 1
        # if child is greater than root(parent), then swap their positions
        if child <= end and _list[root] < _list[child]:
            _list[root], _list[child] = _list[child], _list[root]
            root = child
        else:
            return

