def unshift_vec(vec):
    numerator = line1.slope * vec.x - yintr1 * axis.x * axis.x
    denominator = axis.x * axis.y + line1.slope * axis.y * axis.y

    new_x = numerator / denominator
    new_y = line1.slope * new_x + yintr1

    return vector2.Vector2(new_x, new_y)

