    def my_heuristic(graph, v1, v2):
        dx = v2[0] - v1[0]
        dy = v2[1] - v1[1]
        return math.sqrt(dx * dx + dy * dy)

    return my_pathfinder.find_path(my_graph, v1, v2, my_heuristic)

