def make_set(self, item):
    if item in self.parent:
        return self.find(item)

    self.parent[item] = item
    self.rank[item] = 0
    return item

def find(self, item):
    if item not in self.parent:
        return self.make_set(item)
    if item != self.parent[item]:
        self.parent[item] = self.find(self.parent[item])
    return self.parent[item]

def union(self, item1, item2):
    root1 = self.find(item1)
    root2 = self.find(item2)

    if root1 == root2:
        return root1

    if self.rank[root1] > self.rank[root2]:
        self.parent[root2] = root1
        return root1

    if self.rank[root1] < self.rank[root2]:
        self.parent[root1] = root2
        return root2

    if self.rank[root1] == self.rank[root2]:
        self.rank[root1] += 1
        self.parent[root2] = root1
        return root1
    return None

def compute_ap(graph):
    n = len(graph)
    out_edge_count = 0
    low = [0] * n
    visited = [False] * n
    is_art = [False] * n

    def dfs(root, at, parent, out_edge_count):
        if parent == root:
            out_edge_count += 1
        visited[at] = True
        low[at] = at

        for to in graph[at]:
            if to == parent:
                pass
            elif not visited[to]:
                out_edge_count = dfs(root, to, at, out_edge_count)
                low[at] = min(low[at], low[to])

                # AP found via bridge
                if at < low[to]:
                    is_art[at] = True
                # AP found via cycle
                if at == low[to]:
                    is_art[at] = True
            else:
                low[at] = min(low[at], to)
        return out_edge_count

    for i in range(n):
        if not visited[i]:
            out_edge_count = 0
            out_edge_count = dfs(i, i, -1, out_edge_count)
            is_art[i] = out_edge_count > 1

    for x in range(len(is_art)):
        if is_art[x] is True:
            print(x)

