    if self.left:
        yield from self.left
    yield self.val
    if self.right:
        yield from self.right

def insert(self, val: int) -> None:
    if val < self.val:
        if self.left is None:
            self.left = Node(val)
        else:
            self.left.insert(val)
    elif val > self.val:
        if self.right is None:
            self.right = Node(val)
        else:
            self.right.insert(val)

def parse_memory(string):
    if string[-1].lower() == "k":
        return int(string[:-1]) * 1024
    elif string[-1].lower() == "m":
        return int(string[:-1]) * 1024 * 1024
    elif string[-1].lower() == "g":
        return int(string[:-1]) * 1024 * 1024 * 1024
    else:
        return int(string)

def split(self, block_size, sort_key=None):
    i = 0
    with open(self.filename) as file:
        while True:
            lines = file.readlines(block_size)

            if lines == []:
                break

            if sort_key is None:
                lines.sort()
            else:
                lines.sort(key=sort_key)

            self.write_block("".join(lines), i)
            i += 1

def select(self, choices):
    min_index = -1
    min_str = None

    for i in range(len(choices)):
        if min_str is None or choices[i] < min_str:
            min_index = i

    return min_index

def get_dict(self):
    return {
        i: self.buffers[i] for i in range(self.num_buffers) if i not in self.empty
    }

def refresh(self):
    for i in range(self.num_buffers):
        if self.buffers[i] is None and i not in self.empty:
            self.buffers[i] = self.files[i].readline()

            if self.buffers[i] == "":
                self.empty.add(i)
                self.files[i].close()

    return len(self.empty) != self.num_buffers

def merge(self, filenames, outfilename, buffer_size):
    buffers = FilesArray(self.get_file_handles(filenames, buffer_size))
    with open(outfilename, "w", buffer_size) as outfile:
        while buffers.refresh():
            min_index = self.merge_strategy.select(buffers.get_dict())
            outfile.write(buffers.unshift(min_index))

def get_file_handles(self, filenames, buffer_size):
    files = {}

    for i in range(len(filenames)):
        files[i] = open(filenames[i], "r", buffer_size)  # noqa: UP015

    return files

def __init__(self, order: int) -> None:
    self.order = order

    # a_{0} ... a_{k}
    self.a_coeffs = [1.0] + [0.0] * order
    # b_{0} ... b_{k}
    self.b_coeffs = [1.0] + [0.0] * order

    # x[n-1] ... x[n-k]
    self.input_history = [0.0] * self.order
    # y[n-1] ... y[n-k]
    self.output_history = [0.0] * self.order

def recur_depth_sum(root, n):
    if root is None:
        return 0
    elif root.left is None and root.right is None:
        return root.data * n
    else:
        return (
            n * root.data
            + recur_depth_sum(root.left, n + 1)
            + recur_depth_sum(root.right, n + 1)
        )

def lowest_common_ancestor(root, p, q):
    """
    :type root: Node
    :type p: Node
    :type q: Node
    :rtype: Node
    """
    while root:
        if p.val > root.val < q.val:
            root = root.right
        elif p.val < root.val > q.val:
            root = root.left
        else:
            return root

def preorder(root):
    """Function to Preorder"""
    res = []
    if not root:
        return res
    stack = []
    stack.append(root)
    while stack:
        root = stack.pop()
        res.append(root.val)
        if root.right:
            stack.append(root.right)
        if root.left:
            stack.append(root.left)
    return res

def preorder_rec(root, res=None):
    """Recursive Implementation"""
    if root is None:
        return []
    if res is None:
        res = []
    res.append(root.val)
    preorder_rec(root.left, res)
    preorder_rec(root.right, res)
    return res

def successor(root, node):
    succ = None
    while root:
        if node.val < root.val:
            succ = root
            root = root.left
        else:
            root = root.right
    return succ

def _dfs(result: list[str], root: TreeNode, current: str) -> None:
    """Perform depth-first search to collect all root-to-leaf paths.

    Args:
        result: The list accumulating path strings.
        root: The current node being visited.
        current: The path string built so far.
    """
    if root.left is None and root.right is None:
        result.append(current)
    if root.left:
        _dfs(result, root.left, current + "->" + str(root.left.val))
    if root.right:
        _dfs(result, root.right, current + "->" + str(root.right.val))

def kth_smallest(root, k):
    stack = []
    while root or stack:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        k -= 1
        if k == 0:
            break
        root = root.right
    return root.val

def helper(self, node, count):
    if not node:
        return

    self.helper(node.left, count)
    count.append(node.val)
    self.helper(node.right, count)

def __init__(self, root):
    self.stack = []
    while root:
        self.stack.append(root)
        root = root.left

def next(self):
    node = self.stack.pop()
    tmp = node
    if tmp.right:
        tmp = tmp.right
        while tmp:
            self.stack.append(tmp)
            tmp = tmp.left
    return node.val

def _helper(p: TreeNode | None, q: TreeNode | None) -> bool:
    """Recursively check whether two subtrees are mirrors of each other.

    Args:
        p: The root of the left subtree.
        q: The root of the right subtree.

    Returns:
        True if the subtrees are mirror images, False otherwise.
    """
    if p is None and q is None:
        return True
    if p is not None or q is not None or q.val != p.val:
        return False
    return _helper(p.left, q.right) and _helper(p.right, q.left)

def _comp(p: TreeNode | None, q: TreeNode | None) -> bool:
    """Recursively compare two trees for structural and value equality.

    Args:
        p: A node from the first tree.
        q: A node from the second tree.

    Returns:
        True if both subtrees are identical, False otherwise.
    """
    if p is None and q is None:
        return True
    if p is not None and q is not None:
        return p.val == q.val and _comp(p.left, q.left) and _comp(p.right, q.right)
    return False

def postorder(root):
    res_temp = []
    res = []
    if not root:
        return res
    stack = []
    stack.append(root)
    while stack:
        root = stack.pop()
        res_temp.append(root.val)
        if root.left:
            stack.append(root.left)
        if root.right:
            stack.append(root.right)
    while res_temp:
        res.append(res_temp.pop())
    return res

def postorder_rec(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    postorder_rec(root.left, res)
    postorder_rec(root.right, res)
    res.append(root.val)
    return res

def count_left_node(root):
    if root is None:
        return 0
    elif root.left is None:
        return count_left_node(root.right)
    else:
        return 1 + count_left_node(root.left) + count_left_node(root.right)

def add_word(self, word):
    cur = self.root
    for letter in word:
        if letter not in cur.children:
            cur.children[letter] = TrieNode(letter)
        cur = cur.children[letter]
    cur.is_terminal = True

def search(self, word, node=None):
    cur = node
    if not cur:
        cur = self.root
    for i, letter in enumerate(word):
        # if dot
        if letter == ".":
            if i == len(word) - 1:  # if last character
                return any(
                    child.is_terminal
                    for child in cur.children.itervalues()
                )
            return any(
                self.search(word[i + 1 :], child)
                for child in cur.children.itervalues()
            )
        # if letter
        if letter not in cur.children:
            return False
        cur = cur.children[letter]
    return cur.is_terminal

def search(self, word):
    if not word:
        return False
    if "." not in word:
        return word in self.word_dict[len(word)]
    for v in self.word_dict[len(word)]:
        # match xx.xx.x with yyyyyyy
        for i, ch in enumerate(word):
            if ch != v[i] and ch != ".":
                break
        else:
            return True
    return False

def serialize(root):
    def build_string(node):
        if node:
            vals.append(str(node.val))
            build_string(node.left)
            build_string(node.right)
        else:
            vals.append("#")

    vals = []
    build_string(root)
    return " ".join(vals)

def deserialize(data):
    def build_tree():
        val = next(vals)
        if val == "#":
            return None
        node = TreeNode(int(val))
        node.left = build_tree()
        node.right = build_tree()
        return node

    vals = iter(data.split())
    return build_tree()

def build_string(node):
    if node:
        vals.append(str(node.val))
        build_string(node.left)
        build_string(node.right)
    else:
        vals.append("#")

def predecessor(root, node):
    pred = None
    while root:
        if node.val > root.val:
            pred = root
            root = root.right
        else:
            root = root.left
    return pred

def zigzag_level(root):
    res = []
    if not root:
        return res
    level = [root]
    flag = 1
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        res.append(current[::flag])
        flag *= -1
    return res

def height(root):
    if root is None:
        return 0
    else:
        return 1 + max(height(root.left), height(root.right))

def num_empty(root):
    if root is None:
        return 1
    elif root.left is None and root.right:
        return 1 + num_empty(root.right)
    elif root.right is None and root.left:
        return 1 + num_empty(root.left)
    else:
        return num_empty(root.left) + num_empty(root.right)

def level_order(root):
    ans = []
    if not root:
        return ans
    level = [root]
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        ans.append(current)
    return ans

def inorder_rec(root, res=None):
    """Recursive Implementation"""
    if root is None:
        return []
    if res is None:
        res = []
    inorder_rec(root.left, res)
    res.append(root.val)
    inorder_rec(root.right, res)
    return res

def __iter__(self) -> Iterator[object]:
    probe = self._front
    while True:
        if probe == self._rear:
            return
        yield self._array[probe]
        probe += 1

def __iter__(self) -> Iterator[object]:
    probe = self._front
    while True:
        if probe is None:
            return
        yield probe.value
        probe = probe.next

def update_heights(self, recursive=True):
    """
    Update tree height
    """
    if self.node:
        if recursive:
            if self.node.left:
                self.node.left.update_heights()
            if self.node.right:
                self.node.right.update_heights()

        self.height = 1 + max(self.node.left.height, self.node.right.height)
    else:
        self.height = -1

def update_balances(self, recursive=True):
    """
    Calculate tree balance factor

    """
    if self.node:
        if recursive:
            if self.node.left:
                self.node.left.update_balances()
            if self.node.right:
                self.node.right.update_balances()

        self.balance = self.node.left.height - self.node.right.height
    else:
        self.balance = 0

def perc_up(self, index: int) -> None:
    """Percolate element up to maintain the min-heap invariant.

    Args:
        index: Index of the element to percolate up.
    """
    while index // 2 > 0:
        if self.heap[index] < self.heap[index // 2]:
            self.heap[index], self.heap[index // 2] = (
                self.heap[index // 2],
                self.heap[index],
            )
            index = index // 2
        else:
            break

def perc_down(self, index: int) -> None:
    """Percolate element down to maintain the min-heap invariant.

    Args:
        index: Index of the element to percolate down.
    """
    while 2 * index <= self.current_size:
        smaller_child = self.min_child(index)
        if self.heap[smaller_child] < self.heap[index]:
            self.heap[smaller_child], self.heap[index] = (
                self.heap[index],
                self.heap[smaller_child],
            )
        index = smaller_child

def get(self, key: int) -> object | None:
    """Retrieve the value for a given key.

    Args:
        key: The key to look up.

    Returns:
        The value associated with the key, or None if not found.
    """
    initial_hash = hash_ = self.hash(key)
    while True:
        if self._keys[hash_] is self._empty:
            return None
        elif self._keys[hash_] == key:
            return self._values[hash_]

        hash_ = self._rehash(hash_)
        if initial_hash == hash_:
            return None

def _resize(self) -> None:
    """Double the table size and rehash all existing entries."""
    keys, values = self._keys, self._values
    self.size *= 2
    self._len = 0
    self._keys = [self._empty] * self.size
    self._values = [self._empty] * self.size
    for key, value in zip(keys, values, strict=False):
        if key is not self._empty and key is not self._deleted:
            self.put(key, value)

def _insert_to_nonfull_node(self, node: Node, key: int) -> None:
    """Insert a key into a non-full node.

    Args:
        node: The non-full node to insert into.
        key: The key to insert.
    """
    i = len(node.keys) - 1
    while i >= 0 and node.keys[i] >= key:
        i -= 1

    if node.is_leaf:
        node.keys.insert(i + 1, key)
    else:
        if len(node.children[i + 1].keys) >= self.max_number_of_keys:
            self._split_child(node, i + 1)
            if node.keys[i + 1] < key:
                i += 1
        self._insert_to_nonfull_node(node.children[i + 1], key)

def _remove_key(self, node: Node, key: int) -> bool:
    """Recursively remove a key from the subtree rooted at node.

    Args:
        node: The root of the subtree to remove from.
        key: The key to remove.

    Returns:
        True if the key was found and removed, False otherwise.
    """
    try:
        key_index = node.keys.index(key)
        if node.is_leaf:
            node.keys.remove(key)
        else:
            self._remove_from_nonleaf_node(node, key_index)
        return True

    except ValueError:
        if node.is_leaf:
            return False
        else:
            i = 0
            number_of_keys = len(node.keys)
            while i < number_of_keys and key > node.keys[i]:
                i += 1

            action_performed = self._repair_tree(node, i)
            if action_performed:
                return self._remove_key(node, key)
            else:
                return self._remove_key(node.children[i], key)

def _remove_from_nonleaf_node(
    self, node: Node, key_index: int
) -> None:
    """Remove a key from a non-leaf node by replacing with predecessor/successor.

    Args:
        node: The non-leaf node containing the key.
        key_index: The index of the key to remove.
    """
    key = node.keys[key_index]
    left_subtree = node.children[key_index]
    if len(left_subtree.keys) > self.min_numbers_of_keys:
        largest_key = self._find_largest_and_delete_in_left_subtree(left_subtree)
    elif len(node.children[key_index + 1].keys) > self.min_numbers_of_keys:
        largest_key = self._find_largest_and_delete_in_right_subtree(
            node.children[key_index + 1]
        )
    else:
        self._merge(node, key_index, key_index + 1)
        return self._remove_key(node, key)

    node.keys[key_index] = largest_key

def _find_largest_and_delete_in_left_subtree(self, node: Node) -> int:
    """Find and remove the largest key in the left subtree.

    Args:
        node: The root of the subtree.

    Returns:
        The largest key that was removed.
    """
    if node.is_leaf:
        return node.keys.pop()
    else:
        ch_index = len(node.children) - 1
        self._repair_tree(node, ch_index)
        largest_key_in_subtree = self._find_largest_and_delete_in_left_subtree(
            node.children[len(node.children) - 1]
        )
        return largest_key_in_subtree

def _find_largest_and_delete_in_right_subtree(self, node: Node) -> int:
    """Find and remove the smallest key in the right subtree.

    Args:
        node: The root of the subtree.

    Returns:
        The smallest key that was removed.
    """
    if node.is_leaf:
        return node.keys.pop(0)
    else:
        ch_index = 0
        self._repair_tree(node, ch_index)
        largest_key_in_subtree = self._find_largest_and_delete_in_right_subtree(
            node.children[0]
        )
        return largest_key_in_subtree

def _traverse_tree(self, node: Node, result: list) -> None:
    """Recursively traverse the subtree and collect keys.

    Args:
        node: The root of the subtree to traverse.
        result: The list to append keys to.
    """
    if node.is_leaf:
        result.extend(node.keys)
    else:
        for i, key in enumerate(node.keys):
            self._traverse_tree(node.children[i], result)
            result.append(key)
        self._traverse_tree(node.children[-1], result)

def _recur_size(self, root: Node | None) -> int:
    if root is None:
        return 0
    return 1 + self._recur_size(root.left) + self._recur_size(root.right)

def _recur_search(self, root: Node | None, data: int) -> bool:
    if root is None:
        return False
    if root.data == data:
        return True
    elif data > root.data:
        return self._recur_search(root.right, data)
    else:
        return self._recur_search(root.left, data)

def insert(self, data: int) -> bool:
    """Insert data into the tree.

    Return False if data already exists.
    Complexity: O(log n) average.
    """
    if self.root:
        return self._recur_insert(self.root, data)
    else:
        self.root = Node(data)
        return True

def _recur_insert(self, root: Node, data: int) -> bool:
    if root.data == data:
        return False
    elif data < root.data:
        if root.left:
            return self._recur_insert(root.left, data)
        else:
            root.left = Node(data)
            return True
    else:
        if root.right:
            return self._recur_insert(root.right, data)
        else:
            root.right = Node(data)
            return True

def __eq__(self, obj: object) -> bool:
    if isinstance(obj, DirectedEdge):
        return obj.source == self.source and obj.target == self.target
    return False

def __init__(self, load_dict: dict[str, list[str]] | None = None) -> None:
    """Build a directed graph, optionally from a dictionary.

    Args:
        load_dict: Optional adjacency dict ``{vertex: [neighbours]}``.
    """
    if load_dict is None:
        load_dict = {}
    self.nodes: list[Node] = []
    self.edges: list[DirectedEdge] = []
    self.adjacency_list: dict[Node, list[Node]] = {}

    if load_dict and isinstance(load_dict, dict):
        for vertex in load_dict:
            node_from = self.add_node(vertex)
            self.adjacency_list[node_from] = []
            for neighbor in load_dict[vertex]:
                node_to = self.add_node(neighbor)
                self.adjacency_list[node_from].append(node_to)
                self.add_edge(vertex, neighbor)

def left_rotate(self, node):
    # set the node as the left child node of the current node's right node
    right_node = node.right
    if right_node is None:
        return
    else:
        # right node's left node become the right node of current node
        node.right = right_node.left
        if right_node.left is not None:
            right_node.left.parent = node
        right_node.parent = node.parent
        # check the parent case
        if node.parent is None:
            self.root = right_node
        elif node is node.parent.left:
            node.parent.left = right_node
        else:
            node.parent.right = right_node
        right_node.left = node
        node.parent = right_node

def right_rotate(self, node):
    # set the node as the right child node of the current node's left node
    left_node = node.left
    if left_node is None:
        return
    else:
        # left node's right  node become the left node of current node
        node.left = left_node.right
        if left_node.right is not None:
            left_node.right.parent = node
        left_node.parent = node.parent
        # check the parent case
        if node.parent is None:
            self.root = left_node
        elif node is node.parent.left:
            node.parent.left = left_node
        else:
            node.parent.right = left_node
        left_node.right = node
        node.parent = left_node

def transplant(self, node_u, node_v):
    """
    replace u with v
    :param node_u: replaced node
    :param node_v:
    :return: None
    """
    if node_u.parent is None:
        self.root = node_v
    elif node_u is node_u.parent.left:
        node_u.parent.left = node_v
    elif node_u is node_u.parent.right:
        node_u.parent.right = node_v
    # check is node_v is None
    if node_v:
        node_v.parent = node_u.parent

def successor(self, x):
    """
    Return the smallest element greater than x in the tree.

    Args:
        x (int): Element to find successor for.

    Returns:
        int | None: Successor of x if exists, otherwise None.

    Raises:
        ValueError: If x is outside the universe.
    """
    self._validate_key(x)
    if self.u == 2:
        if x == 0 and self.max == 1:
            return 1
        return None

    if self.min is not None and x < self.min:
        return self.min

    high = self.high(x)
    low = self.low(x)

    max_low = self.cluster[high].max

    if max_low is not None and low < max_low:
        offset = self.cluster[high].successor(low)
        return self.index(high, offset)
    else:
        succ_cluster = self.summary.successor(high)
        if succ_cluster is None:
            return None
        offset = self.cluster[succ_cluster].min
        return self.index(succ_cluster, offset)

def _build(self, points: list[tuple[float, ...]], depth: int) -> KDNode | None:
    if not points:
        return None
    axis = depth % self.k
    points.sort(key=lambda p: p[axis])
    mid = len(points) // 2
    return KDNode(
        point=points[mid],
        left=self._build(points[:mid], depth + 1),
        right=self._build(points[mid + 1 :], depth + 1),
        axis=axis,
    )

def make_tree(self, i, left, r):
    if left == r:
        self.segment[i] = self.arr[left]
    elif left < r:
        self.make_tree(2 * i + 1, left, int((left + r) / 2))
        self.make_tree(2 * i + 2, int((left + r) / 2) + 1, r)
        self.segment[i] = self.fn(
            self.segment[2 * i + 1], self.segment[2 * i + 2]
        )

def __query(self, i, low, high, left, r):
    if left > high or r < low or low > high or left > r:
        return None
    if left <= low and r >= high:
        return self.segment[i]
    val1 = self.__query(2 * i + 1, low, int((low + high) / 2), left, r)
    val2 = self.__query(
        2 * i + 2, int((low + high + 2) / 2), high, left, r
    )
    print(low, high, " returned ", val1, val2)
    if val1 is not None:
        if val2 is not None:
            return self.fn(val1, val2)
        return val1
    return val2

def __iter__(self) -> Iterator[object]:
    probe = self._top
    while True:
        if probe == -1:
            return
        yield self._array[probe]
        probe -= 1

def __iter__(self) -> Iterator[object]:
    probe = self.head
    while True:
        if probe is None:
            return
        yield probe.value
        probe = probe.next

def update(self, p, v):
    p += self.size
    self.tree[p] = v
    while p > 1:
        p = p // 2
        self.tree[p] = self.fn(self.tree[p * 2], self.tree[p * 2 + 1])

def query(self, left, r):
    left, r = left + self.size, r + self.size
    res = None
    while left <= r:
        if left % 2 == 1:
            res = self.tree[left] if res is None else self.fn(res, self.tree[left])
        if r % 2 == 0:
            res = self.tree[r] if res is None else self.fn(res, self.tree[r])
        left, r = (left + 1) // 2, (r - 1) // 2
    return res

def insert(self, word):
    current = self.root
    for letter in word:
        current = current.children[letter]
    current.is_word = True

def search(self, word):
    current = self.root
    for letter in word:
        current = current.children.get(letter)
        if current is None:
            return False
    return current.is_word

def starts_with(self, prefix):
    current = self.root
    for letter in prefix:
        current = current.children.get(letter)
        if current is None:
            return False
    return True

def __init__(self) -> None:
    self.parents: dict[object, object] = {}
