def search_rotate(array: list[int], val: int) -> int:
    """Search for *val* in a rotated sorted *array* (iterative).

    Args:
        array: A sorted list of integers that has been rotated at an
            unknown pivot.
        val: Value to search for.

    Returns:
        Index of *val* in *array*, or -1 if not found.

    Examples:
        >>> search_rotate([4, 5, 6, 7, 0, 1, 2], 0)
        4
        >>> search_rotate([4, 5, 6, 7, 0, 1, 2], 3)
        -1
    """
    low, high = 0, len(array) - 1
    while low <= high:
        mid = (low + high) // 2
        if val == array[mid]:
            return mid

        if array[low] <= array[mid]:
            if array[low] <= val <= array[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:
            if array[mid] <= val <= array[high]:
                low = mid + 1
            else:
                high = mid - 1

    return -1

def search_rotate_recur(
    array: list[int],
    low: int,
    high: int,
    val: int,
) -> int:
    """Search for *val* in a rotated sorted *array* (recursive).

    Args:
        array: A sorted list of integers that has been rotated at an
            unknown pivot.
        low: Lower bound index of the current search range.
        high: Upper bound index of the current search range.
        val: Value to search for.

    Returns:
        Index of *val* in *array*, or -1 if not found.

    Examples:
        >>> search_rotate_recur([4, 5, 6, 7, 0, 1, 2], 0, 6, 0)
        4
    """
    if low >= high:
        return -1
    mid = (low + high) // 2
    if val == array[mid]:
        return mid
    if array[low] <= array[mid]:
        if array[low] <= val <= array[mid]:
            return search_rotate_recur(array, low, mid - 1, val)
        return search_rotate_recur(array, mid + 1, high, val)
    if array[mid] <= val <= array[high]:
        return search_rotate_recur(array, mid + 1, high, val)
    return search_rotate_recur(array, low, mid - 1, val)

def exponential_search(arr: list[int], target: int) -> int:
    """Return the index of *target* in sorted *arr*, or -1 if absent."""
    if not arr:
        return -1
    if arr[0] == target:
        return 0
    bound = 1
    while bound < len(arr) and arr[bound] <= target:
        bound *= 2
    low = bound // 2
    high = min(bound, len(arr) - 1)
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    """Find all words from the list that exist on the board.

    Builds a trie from the word list, then uses backtracking to search
    the board for each word.

    Args:
        board: A 2D grid of characters.
        words: A list of words to search for.

    Returns:
        A list of words found on the board.

    Examples:
        >>> board = [['o','a','a','n'], ['e','t','a','e']]
        >>> sorted(find_words(board, ['eat', 'oath']))
        ['eat']
    """
    trie: dict = {}
    for word in words:
        current_node = trie
        for char in word:
            if char not in current_node:
                current_node[char] = {}
            current_node = current_node[char]
        current_node["#"] = "#"

    found: set[str] = set()
    used = [[False] * len(board[0]) for _ in range(len(board))] if board else []

    for row in range(len(board)):
        for col in range(len(board[0])):
            _backtrack(board, row, col, trie, "", used, found)

    return list(found)

def _backtrack(
    board: list[list[str]],
    row: int,
    col: int,
    trie: dict,
    prefix: str,
    used: list[list[bool]],
    found: set[str],
) -> None:
    """Recursively search the board for words matching the trie."""
    if "#" in trie:
        found.add(prefix)

    if row < 0 or row >= len(board) or col < 0 or col >= len(board[0]):
        return

    if not used[row][col] and board[row][col] in trie:
        used[row][col] = True
        next_char = board[row][col]
        _backtrack(
            board, row + 1, col, trie[next_char], prefix + next_char, used, found
        )
        _backtrack(
            board, row, col + 1, trie[next_char], prefix + next_char, used, found
        )
        _backtrack(
            board, row - 1, col, trie[next_char], prefix + next_char, used, found
        )
        _backtrack(
            board, row, col - 1, trie[next_char], prefix + next_char, used, found
        )
        used[row][col] = False

def permute_iter(elements: list | str) -> Generator:
    """Yield all permutations of the given elements one at a time.

    Args:
        elements: A list or string of distinct elements.

    Yields:
        One permutation at a time (same type as input elements).

    Examples:
        >>> list(permute_iter([1, 2]))
        [[1, 2], [2, 1]]
    """
    if len(elements) <= 1:
        yield elements
    else:
        for perm in permute_iter(elements[1:]):
            for i in range(len(elements)):
                yield perm[:i] + elements[0:1] + perm[i:]

def _dfs(
    result: list[list[int]],
    nums: list[int],
    path: list[int],
) -> None:
    """DFS helper that builds permutations by choosing remaining elements."""
    if not nums:
        result.append(path)
    for i in range(len(nums)):
        _dfs(result, nums[:i] + nums[i + 1 :], path + [nums[i]])

def unique_array_sum_combinations(
    array_a: list[int],
    array_b: list[int],
    array_c: list[int],
    target: int,
) -> list[tuple[int, ...]]:
    """Find unique combinations of one element per array that sum to target.

    Uses itertools.product and filters by target sum, returning only unique
    tuples.

    Args:
        array_a: First array of integers.
        array_b: Second array of integers.
        array_c: Third array of integers.
        target: The desired sum.

    Returns:
        A list of unique tuples that sum to target.

    Examples:
        >>> sorted(unique_array_sum_combinations([1, 2], [2, 3], [3, 4], 6))
        [(1, 2, 3)]
    """

    def _check_sum(expected: int, *nums: int) -> tuple[bool, tuple[int, ...]]:
        if sum(nums) == expected:
            return (True, nums)
        else:
            return (False, nums)

    product = itertools.product(array_a, array_b, array_c)
    func = partial(_check_sum, target)
    sums = list(itertools.starmap(func, product))

    seen: set[tuple[int, ...]] = set()
    for is_match, values in sums:
        if is_match and values not in seen:
            seen.add(values)

    return list(seen)

def _backtrack(
    constructed_so_far: list[int] | None = None,
    result: list[list[int]] | None = None,
) -> None:
    if constructed_so_far is None:
        constructed_so_far = []
    if result is None:
        result = []
    should_stop, reached_target = _is_complete(constructed_so_far)
    if should_stop:
        if reached_target:
            result.append(constructed_so_far)
        return
    candidates = _get_candidates(constructed_so_far)
    for candidate in candidates:
        constructed_so_far.append(candidate)
        _backtrack(constructed_so_far[:], result)
        constructed_so_far.pop()

def _check_sum(expected: int, *nums: int) -> tuple[bool, tuple[int, ...]]:
    if sum(nums) == expected:
        return (True, nums)
    else:
        return (False, nums)

def _factor(
    remaining: int,
    divisor: int,
    partial: list[int],
    combinations: list[list[int]],
) -> list[list[int]]:
    while divisor * divisor <= remaining:
        if remaining % divisor == 0:
            combinations.append(partial + [divisor, remaining // divisor])
            _factor(
                remaining // divisor, divisor, partial + [divisor], combinations
            )
        divisor += 1
    return combinations

def _add_pair_v1(
    result: list[str],
    current: str,
    left: int,
    right: int,
) -> None:
    """Recursive helper for v1: tries closing before opening."""
    if left == 0 and right == 0:
        result.append(current)
        return
    if right > 0:
        _add_pair_v1(result, current + ")", left, right - 1)
    if left > 0:
        _add_pair_v1(result, current + "(", left - 1, right + 1)

def _add_pair_v2(
    result: list[str],
    current: str,
    left: int,
    right: int,
) -> None:
    """Recursive helper for v2: tries opening before closing."""
    if left == 0 and right == 0:
        result.append(current)
    if left > 0:
        _add_pair_v2(result, current + "(", left - 1, right)
    if right > 0 and left < right:
        _add_pair_v2(result, current + ")", left, right - 1)

def _backtrack(
    result: list[str],
    word: str,
    position: int,
    count: int,
    current: str,
) -> None:
    """Recursively build abbreviations by including or skipping characters."""
    if position == len(word):
        if count > 0:
            current += str(count)
        result.append(current)
        return

    if count > 0:
        _backtrack(result, word, position + 1, 0, current + str(count) + word[position])
    else:
        _backtrack(result, word, position + 1, 0, current + word[position])
    _backtrack(result, word, position + 1, count + 1, current)

def _backtrack(
    pattern: str,
    string: str,
    mapping: dict[str, str],
) -> bool:
    """Recursively attempt to match pattern to string using a mapping."""
    if len(pattern) == 0 and len(string) > 0:
        return False

    if len(pattern) == 0 and len(string) == 0:
        return True

    for end in range(1, len(string) - len(pattern) + 2):
        if pattern[0] not in mapping and string[:end] not in mapping.values():
            mapping[pattern[0]] = string[:end]
            if _backtrack(pattern[1:], string[end:], mapping):
                return True
            del mapping[pattern[0]]
        elif pattern[0] in mapping and mapping[pattern[0]] == string[:end]:
            if _backtrack(pattern[1:], string[end:], mapping):
                return True
    return False

def _dfs(
    nums: list[int],
    target: int,
    index: int,
    path: list[int],
    result: list[list[int]],
) -> None:
    """Depth-first search helper for building combinations."""
    if target < 0:
        return
    if target == 0:
        result.append(path)
        return
    for i in range(index, len(nums)):
        _dfs(nums, target - nums[i], i, path + [nums[i]], result)

def shortest_distance(grid: list[list[int]]) -> int:
    """Return the minimum total distance from an empty cell to all buildings.

    Args:
        grid: 2D grid (0 = empty, 1 = building, 2 = obstacle).

    Returns:
        Minimum sum of distances, or -1 if impossible.

    Examples:
        >>> shortest_distance([[1, 0, 1]])
        2
    """
    if not grid or not grid[0]:
        return -1

    matrix = [[[0, 0] for _ in range(len(grid[0]))] for _ in range(len(grid))]

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                _bfs(grid, matrix, i, j, count)
                count += 1

    res = float("inf")
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j][1] == count:
                res = min(res, matrix[i][j][0])

    return res if res != float("inf") else -1

def add_edge(self, source: int, target: int) -> None:
    """Add a directed edge.

    Args:
        source: Source vertex.
        target: Target vertex.
    """
    if source in self.graph:
        self.graph[source].append(target)
    else:
        self.graph[source] = [target]

def _dfs_util(self, source: int, target: int) -> None:
    """Recursive DFS marking reachability from *source* through *target*.

    Args:
        source: Origin vertex.
        target: Current vertex being explored.
    """
    self.closure[source][target] = 1

    for adjacent in self.graph[target]:
        if self.closure[source][adjacent] == 0:
            self._dfs_util(source, adjacent)

def clone_graph1(node: UndirectedGraphNode | None) -> UndirectedGraphNode | None:
    """Clone a graph using BFS.

    Args:
        node: Any node in the original graph.

    Returns:
        The corresponding node in the cloned graph, or None.
    """
    if not node:
        return None
    node_copy = node.shallow_copy()
    dic: dict[UndirectedGraphNode, UndirectedGraphNode] = {node: node_copy}
    queue: collections.deque[UndirectedGraphNode] = collections.deque([node])
    while queue:
        node = queue.popleft()
        for neighbor in node.neighbors:
            if neighbor not in dic:
                neighbor_copy = neighbor.shallow_copy()
                dic[neighbor] = neighbor_copy
                dic[node].add_neighbor(neighbor_copy)
                queue.append(neighbor)
            else:
                dic[node].add_neighbor(dic[neighbor])
    return node_copy

def clone_graph2(node: UndirectedGraphNode | None) -> UndirectedGraphNode | None:
    """Clone a graph using iterative DFS.

    Args:
        node: Any node in the original graph.

    Returns:
        The corresponding node in the cloned graph, or None.
    """
    if not node:
        return None
    node_copy = node.shallow_copy()
    dic: dict[UndirectedGraphNode, UndirectedGraphNode] = {node: node_copy}
    stack = [node]
    while stack:
        node = stack.pop()
        for neighbor in node.neighbors:
            if neighbor not in dic:
                neighbor_copy = neighbor.shallow_copy()
                dic[neighbor] = neighbor_copy
                dic[node].add_neighbor(neighbor_copy)
                stack.append(neighbor)
            else:
                dic[node].add_neighbor(dic[neighbor])
    return node_copy

def shallow_copy(self) -> UndirectedGraphNode:
    """Return a copy of this node without neighbours.

    Returns:
        A new node with the same label.
    """
    return UndirectedGraphNode(self.label)

def bellman_ford(graph: dict[str, dict[str, float]], source: str) -> bool:
    """Compute shortest paths from *source* and detect negative cycles.

    Args:
        graph: Weighted directed graph as
            ``{node: {neighbor: edge_weight, ...}, ...}``.
        source: The starting vertex.

    Returns:
        True if shortest paths were computed (no negative cycle), False
        otherwise.

    Examples:
        >>> g = {'a': {'b': 1}, 'b': {'c': 2}, 'c': {}}
        >>> bellman_ford(g, 'a')
        True
    """
    distance: dict[str, float] = {}
    predecessor: dict[str, str | None] = {}

    _initialize_single_source(graph, source, distance, predecessor)

    num_vertices = len(graph)
    for _ in range(1, num_vertices):
        for current_node in graph:
            for neighbor in graph[current_node]:
                edge_weight = graph[current_node][neighbor]
                if distance[neighbor] > distance[current_node] + edge_weight:
                    distance[neighbor] = distance[current_node] + edge_weight
                    predecessor[neighbor] = current_node

    for current_node in graph:
        for neighbor in graph[current_node]:
            edge_weight = graph[current_node][neighbor]
            if distance[neighbor] > distance[current_node] + edge_weight:
                return False

    return True

def _expand_clique(candidates: set[str], nays: set[str]) -> None:
    if not candidates and not nays:
        solutions.append(compsub.copy())
    else:
        for selected in candidates.copy():
            candidates.remove(selected)
            candidates_temp = _get_connected(selected, candidates)
            nays_temp = _get_connected(selected, nays)
            compsub.append(selected)
            _expand_clique(candidates_temp, nays_temp)
            nays.add(compsub.pop())

def _get_connected(vertex: str, old_set: set[str]) -> set[str]:
    new_set: set[str] = set()
    for neighbor in edges[str(vertex)]:
        if neighbor in old_set:
            new_set.add(neighbor)
    return new_set

def _factor(
    n: int,
    i: int,
    combi: list[int],
    res: list[list[int]],
) -> list[list[int]]:
    while i * i <= n:
        if n % i == 0:
            res += (combi + [i, int(n / i)],)
            _factor(n / i, i, combi + [i], res)
        i += 1
    return res

def walls_and_gates(rooms: list[list[int]]) -> None:
    """Fill *rooms* in place with distances to nearest gates.

    Args:
        rooms: 2D grid (-1 = wall, 0 = gate, INF = empty room).

    Examples:
        >>> r = [[float('inf'), 0]]; walls_and_gates(r); r
        [[1, 0]]
    """
    for i in range(len(rooms)):
        for j in range(len(rooms[0])):
            if rooms[i][j] == 0:
                _dfs(rooms, i, j, 0)

def _word_range(word: str) -> Iterator[str]:
    """Yield all words that differ from *word* by exactly one letter.

    Args:
        word: The source word.

    Yields:
        Words with a single character changed.
    """
    for ind in range(len(word)):
        temp = word[ind]
        for c in [chr(x) for x in range(ord("a"), ord("z") + 1)]:
            if c != temp:
                yield word[:ind] + c + word[ind + 1 :]

def _scc(graph: dict[Any, list[Any]]) -> dict[Any, int]:
    """Compute SCCs using Kosaraju's algorithm.

    Args:
        graph: Directed graph adjacency list.

    Returns:
        Mapping from vertex to its SCC index.
    """
    order: list[Any] = []
    visited = {vertex: False for vertex in graph}

    graph_transposed: dict[Any, list[Any]] = {vertex: [] for vertex in graph}

    for source, neighbours in graph.items():
        for target in neighbours:
            _add_edge(graph_transposed, target, source)

    for vertex in graph:
        if not visited[vertex]:
            _dfs_transposed(vertex, graph_transposed, order, visited)

    visited = {vertex: False for vertex in graph}
    vertex_scc: dict[Any, int] = {}

    current_comp = 0
    for vertex in reversed(order):
        if not visited[vertex]:
            _dfs(vertex, current_comp, vertex_scc, graph, visited)
            current_comp += 1

    return vertex_scc

def _build_graph(
    formula: list[tuple[tuple[str, bool], tuple[str, bool]]],
) -> dict[tuple[str, bool], list[tuple[str, bool]]]:
    """Build the implication graph from a 2-CNF formula.

    Args:
        formula: List of clauses, each a pair of literals
            ``(name, is_negated)``.

    Returns:
        Implication graph as an adjacency list.
    """
    graph: dict[tuple[str, bool], list[tuple[str, bool]]] = {}

    for clause in formula:
        for lit, _ in clause:
            for neg in [False, True]:
                graph[(lit, neg)] = []

    for (a_lit, a_neg), (b_lit, b_neg) in formula:
        _add_edge(graph, (a_lit, a_neg), (b_lit, not b_neg))
        _add_edge(graph, (b_lit, b_neg), (a_lit, not a_neg))

    return graph

def solve_sat(
    formula: list[tuple[tuple[str, bool], tuple[str, bool]]],
) -> dict[str, bool] | None:
    """Solve a 2-SAT formula.

    Args:
        formula: List of clauses in 2-CNF.

    Returns:
        A satisfying assignment as ``{variable: value}`` or None if
        unsatisfiable.

    Examples:
        >>> solve_sat([(('x', False), ('y', False)), (('x', True), ('y', True))])
        {'x': False, 'y': False}
    """
    graph = _build_graph(formula)
    vertex_scc = _scc(graph)

    for var, _ in graph:
        if vertex_scc[(var, False)] == vertex_scc[(var, True)]:
            return None

    comp_repr: dict[int, tuple[str, bool]] = {}

    for vertex in graph:
        if vertex_scc[vertex] not in comp_repr:
            comp_repr[vertex_scc[vertex]] = vertex

    comp_value: dict[int, bool] = {}
    components = sorted(vertex_scc.values())

    for comp in components:
        if comp not in comp_value:
            comp_value[comp] = False
            lit, neg = comp_repr[comp]
            comp_value[vertex_scc[(lit, not neg)]] = True

    value = {var: comp_value[vertex_scc[(var, False)]] for var, _ in graph}

    return value

def _dfs(node: str) -> None:
    state[node] = _GRAY
    for neighbour in graph.get(node, ()):
        neighbour_state = state.get(neighbour)
        if neighbour_state == _GRAY:
            raise ValueError("cycle")
        if neighbour_state == _BLACK:
            continue
        enter.discard(neighbour)
        _dfs(neighbour)
    order.append(node)
    state[node] = _BLACK

def _is_ready(node: str) -> bool:
    neighbours = graph.get(node, ())
    if len(neighbours) == 0:
        return True
    for neighbour in neighbours:
        neighbour_state = state.get(neighbour)
        if neighbour_state == _GRAY:
            raise ValueError("cycle")
        if neighbour_state != _BLACK:
            return False
    return True

def find_augmenting_path() -> bool:
    """Try to find an augmenting path from any free vertex."""
    parent = [-1] * n
    visited = [False] * n
    for start in range(n):
        if match[start] != -1:
            continue
        # BFS from this free vertex
        queue: deque[int] = deque([start])
        visited[start] = True
        found = False
        while queue and not found:
            u = queue.popleft()
            for v in adj[u]:
                if visited[v] or v == match[u]:
                    continue
                if match[v] == -1 and v != start:
                    # Augmenting path found — trace back and flip
                    _augment(parent, match, u, v)
                    return True
                if match[v] != -1:
                    visited[v] = True
                    visited[match[v]] = True
                    parent[match[v]] = u
                    queue.append(match[v])
    return False

def _dfs_util(self, source: int, visited: list[bool]) -> None:
    """Recursive DFS helper.

    Args:
        source: Current vertex.
        visited: Visited flags (modified in place).
    """
    visited[source] = True
    for adjacent in self.graph[source]:
        if not visited[adjacent]:
            self._dfs_util(adjacent, visited)

def reverse_graph(self) -> Graph:
    """Return a new graph with every edge reversed.

    Returns:
        A new Graph instance with reversed edges.
    """
    reverse = Graph(self.vertex_count)
    for source, adjacent in self.graph.items():
        for target in adjacent:
            reverse.add_edge(target, source)
    return reverse

def is_strongly_connected(self) -> bool:
    """Return True if the graph is strongly connected.

    Returns:
        True when every vertex can reach every other vertex.
    """
    if self.dfs():
        reversed_graph = self.reverse_graph()
        if reversed_graph.dfs():
            return True
    return False

def _possible_values(self) -> dict[tuple[int, int], list[str]]:
    """Compute possible values for each empty cell.

    Returns:
        Mapping from (row, col) to list of candidate digits.
    """
    a = "123456789"
    d: dict[tuple[str, int] | tuple[int, int], list[str]] = {}
    val: dict[tuple[int, int], list[str]] = {}
    for i in range(self.row):
        for j in range(self.col):
            ele = self.board[i][j]
            if ele != ".":
                d[("r", i)] = d.get(("r", i), []) + [ele]
                d[("c", j)] = d.get(("c", j), []) + [ele]
                d[(i // 3, j // 3)] = d.get((i // 3, j // 3), []) + [ele]
            else:
                val[(i, j)] = []
    for i, j in val:
        inval = (
            d.get(("r", i), []) + d.get(("c", j), []) + d.get((i / 3, j / 3), [])
        )
        val[(i, j)] = [n for n in a if n not in inval]
    return val

def solve(self) -> bool:
    """Attempt to solve the board in place.

    Returns:
        True if a solution was found.
    """
    if len(self.val) == 0:
        return True
    kee = min(self.val.keys(), key=lambda x: len(self.val[x]))
    nums = self.val[kee]
    for n in nums:
        update: dict[tuple[int, int], str | list[str]] = {kee: self.val[kee]}
        if self._valid_one(n, kee, update) and self.solve():
                return True
        self._undo(kee, update)
    return False

def _undo(
    self,
    kee: tuple[int, int],
    update: dict[tuple[int, int], str | list[str]],
) -> None:
    """Revert the placement at *kee* using *update*.

    Args:
        kee: (row, col) coordinate.
        update: Undo log.
    """
    self.board[kee[0]][kee[1]] = "."
    for k in update:
        if k not in self.val:
            self.val[k] = update[k]
        else:
            self.val[k].append(update[k])

def _binary_search(job: list[Job], start_index: int) -> int:
    """Find the latest non-conflicting job before start_index.

    Args:
        job: List of jobs sorted by finish time.
        start_index: Index of the current job.

    Returns:
        Index of the latest compatible job, or -1 if none exists.
    """
    left = 0
    right = start_index - 1

    while left <= right:
        mid = (left + right) // 2
        if job[mid].finish <= job[start_index].start:
            if job[mid + 1].finish <= job[start_index].start:
                left = mid + 1
            else:
                return mid
        else:
            right = mid - 1
    return -1

def count_paths_recursive(m: int, n: int) -> int:
    """Naive recursive solution — O(2^(m+n))."""
    if m == 1 or n == 1:
        return 1
    return count_paths_recursive(m - 1, n) + count_paths_recursive(m, n - 1)

def count_paths_memo(m: int, n: int) -> int:
    """Top-down DP with memoization — O(m*n)."""

    @cache
    def helper(i: int, j: int) -> int:
        if i == 1 or j == 1:
            return 1
        return helper(i - 1, j) + helper(i, j - 1)

    return helper(m, n)

def helper(i: int, j: int) -> int:
    if i == 1 or j == 1:
        return 1
    return helper(i - 1, j) + helper(i, j - 1)

def tsp(dist: list[list[float]]) -> float:
    """Return the minimum cost of a Hamiltonian cycle.

    *dist* is an n x n distance matrix.

    >>> tsp([[0, 10, 15, 20],
    ...      [10, 0, 35, 25],
    ...      [15, 35, 0, 30],
    ...      [20, 25, 30, 0]])
    80
    """
    n = len(dist)
    full_mask = (1 << n) - 1
    dp: dict[tuple[int, int], float] = {}

    def solve(mask: int, pos: int) -> float:
        if mask == full_mask:
            return dist[pos][0]
        key = (mask, pos)
        if key in dp:
            return dp[key]
        ans = math.inf
        for city in range(n):
            if not (mask & (1 << city)):
                ans = min(ans, dist[pos][city] + solve(mask | (1 << city), city))
        dp[key] = ans
        return ans

    return solve(1, 0)

def solve(mask: int, pos: int) -> float:
    if mask == full_mask:
        return dist[pos][0]
    key = (mask, pos)
    if key in dp:
        return dp[key]
    ans = math.inf
    for city in range(n):
        if not (mask & (1 << city)):
            ans = min(ans, dist[pos][city] + solve(mask | (1 << city), city))
    dp[key] = ans
    return ans

def _update(pos: int, left: int, right: int, target: int, vertex: int) -> None:
    if left == right:
        tree[pos] = vertex
        return
    mid = (left + right) >> 1
    if target <= mid:
        _update(pos << 1, left, mid, target, vertex)
    else:
        _update((pos << 1) | 1, mid + 1, right, target, vertex)
    tree[pos] = max(tree[pos << 1], tree[(pos << 1) | 1])

def _get_max(pos: int, left: int, right: int, start: int, end: int) -> int:
    if left > end or right < start:
        return 0
    if left >= start and right <= end:
        return tree[pos]
    mid = (left + right) >> 1
    return max(
        _get_max(pos << 1, left, mid, start, end),
        _get_max((pos << 1) | 1, mid + 1, right, start, end),
    )

def hosoya(height: int, width: int) -> int:
    """Compute a single entry in the Hosoya triangle.

    Args:
        height: Row index (0-based).
        width: Column index (0-based).

    Returns:
        The value at position (height, width) in the Hosoya triangle.

    Examples:
        >>> hosoya(4, 2)
        4
    """
    if (width == 0) and (height in (0, 1)):
        return 1
    if (width == 1) and (height in (1, 2)):
        return 1
    if height > width:
        return hosoya(height - 1, width) + hosoya(height - 2, width)
    if width == height:
        return hosoya(height - 1, width - 1) + hosoya(height - 2, width - 2)
    return 0

def is_palindrome_dict(head: object | None) -> bool:
    """Check if a linked list is a palindrome using a dictionary of positions.

    Builds a dictionary mapping each value to its list of positions, then
    verifies that positions are symmetric around the center.

    Args:
        head: Head node of the linked list.

    Returns:
        True if the list is a palindrome, False otherwise.

    Examples:
        >>> is_palindrome_dict(None)
        True
    """
    if not head or not head.next:
        return True
    positions: dict[object, list[int]] = {}
    pos = 0
    current = head
    while current:
        if current.val in positions:
            positions[current.val].append(pos)
        else:
            positions[current.val] = [pos]
        current = current.next
        pos += 1
    checksum = pos - 1
    middle = 0
    for indices in positions.values():
        if len(indices) % 2 != 0:
            middle += 1
        else:
            for step, i in enumerate(range(len(indices))):
                if indices[i] + indices[len(indices) - 1 - step] != checksum:
                    return False
        if middle > 1:
            return False
    return True

def remove_range(head: object | None, start: int, end: int) -> object | None:
    """Remove nodes from index start to end (inclusive) from a linked list.

    Args:
        head: Head node of the linked list (must have .next attr).
        start: Starting index of the range to remove.
        end: Ending index of the range to remove (inclusive).

    Returns:
        The (possibly new) head of the modified list.

    Examples:
        >>> remove_range(None, 0, 0) is None
        True
    """
    assert start <= end
    if start == 0:
        for _ in range(end + 1):
            if head is not None:
                head = head.next
    else:
        current = head
        for _ in range(start - 1):
            current = current.next
        for _ in range(end - start + 1):
            if current is not None and current.next is not None:
                current.next = current.next.next
    return head

def _prime_check(num: int) -> bool:
    """Check whether a number is prime.

    Args:
        num: The integer to test.

    Returns:
        True if num is prime, False otherwise.
    """
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    j = 5
    while j * j <= num:
        if num % j == 0 or num % (j + 2) == 0:
            return False
        j += 6
    return True

def _find_order(a: int, n: int) -> int:
    """Find the multiplicative order of a modulo n.

    Args:
        a: The base integer.
        n: The modulus.

    Returns:
        The smallest positive k such that a^k = 1 (mod n), or -1 if none exists.
    """
    if (a == 1) & (n == 1):
        return 1
    if math.gcd(a, n) != 1:
        return -1
    for i in range(1, n):
        if pow(a, i) % n == 1:
            return i
    return -1

def _euler_totient(n: int) -> int:
    """Compute Euler's totient function phi(n).

    Args:
        n: A positive integer.

    Returns:
        The number of integers from 1 to n that are coprime with n.
    """
    result = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

def _modinv(a: int, m: int) -> int:
    g, x, _ = _extended_gcd(a, m)
    if g != 1:
        raise ValueError(f"Modular inverse does not exist: gcd({a}, {m}) = {g}")
    return x % m

def _gen_prime(k: int, seed: int | None = None) -> int:
    """Generate a random prime with k bits.

    Args:
        k: The number of bits.
        seed: Unused, kept for API compatibility.

    Returns:
        A prime number.
    """

    def _is_prime(num: int) -> bool:
        if num == 2:
            return True
        return all(
            num % i != 0
            for i in range(2, int(num**0.5) + 1)
        )

    while True:
        key = secrets.randbelow(int(2**k) - int(2 ** (k - 1))) + int(2 ** (k - 1))
        if _is_prime(key):
            return key

def _is_prime(num: int) -> bool:
    if num == 2:
        return True
    return all(
        num % i != 0
        for i in range(2, int(num**0.5) + 1)
    )

def _find_order(a: int, n: int) -> int:
    """Find the multiplicative order of a modulo n.

    Args:
        a: The base integer.
        n: The modulus.

    Returns:
        The smallest positive k where a^k = 1 (mod n), or -1 if none exists.
    """
    if (a == 1) & (n == 1):
        return 1
    if math.gcd(a, n) != 1:
        return -1
    for i in range(1, n):
        if pow(a, i) % n == 1:
            return i
    return -1

def _euler_totient(n: int) -> int:
    """Compute Euler's totient function phi(n).

    Args:
        n: A positive integer.

    Returns:
        The count of integers in [1, n] coprime to n.
    """
    result = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

def combination_memo(n: int, r: int) -> int:
    """Calculate nCr using memoization.

    Args:
        n: Total number of items.
        r: Number of items to choose.

    Returns:
        The number of combinations.

    Examples:
        >>> combination_memo(50, 10)
        10272278170
    """
    memo: dict[tuple[int, int], int] = {}

    def _recur(n: int, r: int) -> int:
        if n == r or r == 0:
            return 1
        if (n, r) not in memo:
            memo[(n, r)] = _recur(n - 1, r - 1) + _recur(n - 1, r)
        return memo[(n, r)]

    return _recur(n, r)

def _recur(n: int, r: int) -> int:
    if n == r or r == 0:
        return 1
    if (n, r) not in memo:
        memo[(n, r)] = _recur(n - 1, r - 1) + _recur(n - 1, r)
    return memo[(n, r)]

def solve_chinese_remainder(nums: list[int], rems: list[int]) -> int:
    """Find the smallest x satisfying x % nums[i] == rems[i] for all i.

    Args:
        nums: List of pairwise coprime moduli, each greater than 1.
        rems: List of remainders corresponding to each modulus.

    Returns:
        The smallest positive integer satisfying all congruences.

    Raises:
        Exception: If inputs are invalid or moduli are not pairwise coprime.

    Examples:
        >>> solve_chinese_remainder([3, 7, 10], [2, 3, 3])
        143
    """
    if not len(nums) == len(rems):
        raise Exception("nums and rems should have equal length")
    if not len(nums) > 0:
        raise Exception("Lists nums and rems need to contain at least one element")
    for num in nums:
        if not num > 1:
            raise Exception("All numbers in nums needs to be > 1")
    if not _check_coprime(nums):
        raise Exception("All pairs of numbers in nums are not coprime")
    k = len(nums)
    x = 1
    while True:
        i = 0
        while i < k:
            if x % nums[i] != rems[i]:
                break
            i += 1
        if i == k:
            return x
        x += 1

def _check_coprime(list_to_check: list[int]) -> bool:
    """Check whether all pairs of numbers in the list are coprime.

    Args:
        list_to_check: List of integers to check for pairwise coprimality.

    Returns:
        True if all pairs are coprime, False otherwise.
    """
    for ind, num in enumerate(list_to_check):
        for num2 in list_to_check[ind + 1 :]:
            if gcd(num, num2) != 1:
                return False
    return True

def rmse(x: list[float], y: list[float]) -> float:
    """Return the root mean squared error for the fit."""
    slope, intercept = linear_regression(x, y)
    n = len(y)
    return math.sqrt(
        sum((yi - (slope * xi + intercept)) ** 2 for xi, yi in zip(x, y, strict=False))
        / n
    )

def pythagoras(
    opposite: float | str, adjacent: float | str, hypotenuse: float | str
) -> str:
    """Compute the unknown side of a right triangle.

    Pass "?" as the unknown side to calculate it from the other two.

    Args:
        opposite: Length of the opposite side, or "?" if unknown.
        adjacent: Length of the adjacent side, or "?" if unknown.
        hypotenuse: Length of the hypotenuse, or "?" if unknown.

    Returns:
        A string describing the computed side and its value.

    Raises:
        ValueError: If the arguments are invalid.

    Examples:
        >>> pythagoras(3, 4, "?")
        'Hypotenuse = 5.0'
    """
    try:
        if opposite == "?":
            return "Opposite = " + str(((hypotenuse**2) - (adjacent**2)) ** 0.5)
        if adjacent == "?":
            return "Adjacent = " + str(((hypotenuse**2) - (opposite**2)) ** 0.5)
        if hypotenuse == "?":
            return "Hypotenuse = " + str(((opposite**2) + (adjacent**2)) ** 0.5)
        return "You already know the answer!"
    except Exception as err:
        raise ValueError("invalid argument(s) were given.") from err

def _rationalize_if_possible(
    num: int | float | Fraction,
) -> Fraction | float:
    """Convert numbers to Fraction when possible.

    Args:
        num: A numeric value.

    Returns:
        A Fraction if the input is Rational, otherwise the original value.
    """
    if isinstance(num, Rational):
        res = Fraction(num, 1)
        return Fraction(res.numerator, res.denominator)
    else:
        return num

def __add__(self, other: int | float | Fraction) -> Monomial:
    """Add two monomials or a monomial with a scalar.

    Args:
        other: A Monomial, int, float, or Fraction to add.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If monomials have different variables.
    """
    if isinstance(other, (int, float, Fraction)):
        return self.__add__(Monomial({}, Monomial._rationalize_if_possible(other)))

    if not isinstance(other, Monomial):
        raise ValueError("Can only add monomials, ints, floats, or Fractions.")

    if self.variables == other.variables:
        mono = {i: self.variables[i] for i in self.variables}
        return Monomial(
            mono, Monomial._rationalize_if_possible(self.coeff + other.coeff)
        ).clean()

    raise ValueError(
        f"Cannot add {str(other)} to {self.__str__()} "
        "because they don't have same variables."
    )

def __mul__(self, other: int | float | Fraction) -> Monomial:
    """Multiply two monomials or a monomial with a scalar.

    Args:
        other: A Monomial, int, float, or Fraction to multiply.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If other is not a valid type.
    """
    if isinstance(other, (float, int, Fraction)):
        mono = {i: self.variables[i] for i in self.variables}
        return Monomial(
            mono, Monomial._rationalize_if_possible(self.coeff * other)
        ).clean()

    if not isinstance(other, Monomial):
        raise ValueError("Can only multiply monomials, ints, floats, or Fractions.")
    else:
        mono = {i: self.variables[i] for i in self.variables}
        for i in other.variables:
            if i in mono:
                mono[i] += other.variables[i]
            else:
                mono[i] = other.variables[i]

        temp = dict()
        for k in mono:
            if mono[k] != 0:
                temp[k] = mono[k]

        return Monomial(
            temp, Monomial._rationalize_if_possible(self.coeff * other.coeff)
        ).clean()

def inverse(self) -> Monomial:
    """Compute the multiplicative inverse of this monomial.

    Returns:
        The inverse Monomial.

    Raises:
        ValueError: If the coefficient is zero.
    """
    mono = {i: self.variables[i] for i in self.variables if self.variables[i] != 0}
    for i in mono:
        mono[i] *= -1
    if self.coeff == 0:
        raise ValueError("Coefficient must not be 0.")
    return Monomial(mono, Monomial._rationalize_if_possible(1 / self.coeff)).clean()

def __truediv__(self, other: int | float | Fraction) -> Monomial:
    """Divide this monomial by another monomial or scalar.

    Args:
        other: A Monomial, int, float, or Fraction divisor.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If dividing by zero.
    """
    if isinstance(other, (int, float, Fraction)):
        mono = {i: self.variables[i] for i in self.variables}
        if other == 0:
            raise ValueError("Cannot divide by 0.")
        return Monomial(
            mono, Monomial._rationalize_if_possible(self.coeff / other)
        ).clean()

    o = other.inverse()
    return self.__mul__(o)

def clone(self) -> Monomial:
    """Create a deep copy of this monomial.

    Returns:
        A new Monomial with the same variables and coefficient.
    """
    temp_variables = {i: self.variables[i] for i in self.variables}
    return Monomial(
        temp_variables, Monomial._rationalize_if_possible(self.coeff)
    ).clean()

def clean(self) -> Monomial:
    """Remove variables with zero power.

    Returns:
        A cleaned Monomial.
    """
    temp_variables = {
        i: self.variables[i] for i in self.variables if self.variables[i] != 0
    }
    return Monomial(temp_variables, Monomial._rationalize_if_possible(self.coeff))

def __sub__(self, other: int | float | Fraction) -> Monomial:
    """Subtract a value from this monomial.

    Args:
        other: A Monomial, int, float, or Fraction to subtract.

    Returns:
        The resulting Monomial.

    Raises:
        ValueError: If monomials have different variables.
    """
    if isinstance(other, (int, float, Fraction)):
        mono = {
            i: self.variables[i] for i in self.variables if self.variables[i] != 0
        }
        if len(mono) != 0:
            raise ValueError("Can only subtract like monomials.")
        other_term = Monomial(mono, Monomial._rationalize_if_possible(other))
        return self.__sub__(other_term)
    if not isinstance(other, Monomial):
        raise ValueError("Can only subtract monomials")
    return self.__add__(other.__mul__(Fraction(-1, 1)))

def __hash__(self) -> int:
    """Hash based on the underlying variables.

    Returns:
        An integer hash value.
    """
    arr = []
    for i in sorted(self.variables):
        if self.variables[i] > 0:
            for _ in range(self.variables[i]):
                arr.append(i)
    return hash(tuple(arr))

def all_variables(self) -> set:
    """Get the set of all variable indices in this monomial.

    Returns:
        A set of variable indices.
    """
    return set(sorted(self.variables.keys()))

def substitute(
    self,
    substitutions: int | float | Fraction | dict[int, int | float | Fraction],
) -> Fraction:
    """Evaluate the monomial by substituting values for variables.

    Args:
        substitutions: A single value applied to all variables, or a
            dict mapping variable indices to values.

    Returns:
        The evaluated result.

    Raises:
        ValueError: If some variables are not given values.
    """
    if isinstance(substitutions, (int, float, Fraction)):
        substitutions = {
            v: Monomial._rationalize_if_possible(substitutions)
            for v in self.all_variables()
        }
    else:
        if not self.all_variables().issubset(set(substitutions.keys())):
            raise ValueError("Some variables didn't receive their values.")
    if self.coeff == 0:
        return Fraction(0, 1)
    ans = Monomial._rationalize_if_possible(self.coeff)
    for k in self.variables:
        ans *= Monomial._rationalize_if_possible(
            substitutions[k] ** self.variables[k]
        )
    return Monomial._rationalize_if_possible(ans)

def __str__(self) -> str:
    """Get a string representation of the monomial.

    Returns:
        A human-readable string.
    """
    if len(self.variables) == 0:
        return str(self.coeff)

    result = str(self.coeff)
    result += "("
    for i in self.variables:
        temp = f"a_{str(i)}"
        if self.variables[i] > 1:
            temp = "(" + temp + f")**{self.variables[i]}"
        elif self.variables[i] < 0:
            temp = "(" + temp + f")**(-{-self.variables[i]})"
        elif self.variables[i] == 0:
            continue
        else:
            temp = "(" + temp + ")"
        result += temp
    return result + ")"

def __init__(
    self, monomials: Iterable[int | float | Fraction | Monomial]
) -> None:
    """Create a polynomial from an iterable of monomials or scalars.

    Args:
        monomials: An iterable of Monomial, int, float, or Fraction values.

    Raises:
        ValueError: If an element is not a valid type.
    """
    self.monomials: set = set()
    for m in monomials:
        if any(map(lambda x: isinstance(m, x), [int, float, Fraction])):
            self.monomials |= {Monomial({}, m)}
        elif isinstance(m, Monomial):
            self.monomials |= {m}
        else:
            raise ValueError(
                "Iterable should have monomials, int, float, or Fraction."
            )
    self.monomials -= {Monomial({}, 0)}

def __mul__(self, other: int | float | Fraction | Monomial) -> Polynomial:
    """Multiply this polynomial by another polynomial, monomial, or scalar.

    Args:
        other: Value to multiply by.

    Returns:
        The resulting Polynomial.

    Raises:
        ValueError: If other is not a valid type.
    """
    if isinstance(other, (int, float, Fraction, Monomial)):
        result = Polynomial([])
        monos = {m.clone() for m in self.all_monomials()}
        for m in monos:
            result = result.__add__(m.clone() * other)
        return result
    elif isinstance(other, Polynomial):
        temp_self = {m.clone() for m in self.all_monomials()}
        temp_other = {m.clone() for m in other.all_monomials()}

        result = Polynomial([])

        for i in temp_self:
            for j in temp_other:
                result = result.__add__(i * j)

        return result
    else:
        raise ValueError(
            "Can only multiple int, float, Fraction, "
            "Monomials, or Polynomials with Polynomials."
        )

def clone(self) -> Polynomial:
    """Create a deep copy of this polynomial.

    Returns:
        A new Polynomial with cloned monomials.
    """
    return Polynomial(list({m.clone() for m in self.all_monomials()}))

def variables(self) -> set:
    """Get all variable indices present in this polynomial.

    Returns:
        A set of variable indices.
    """
    res = set()
    for i in self.all_monomials():
        res |= {j for j in i.variables}
    res = list(res)
    return set(res)

def all_monomials(self) -> Iterable[Monomial]:
    """Get all non-zero monomials in this polynomial.

    Returns:
        A set of Monomial terms.
    """
    return {m for m in self.monomials if m != Monomial({}, 0)}

def __eq__(self, other: object) -> bool:
    """Check equality of two polynomials.

    Args:
        other: Another Polynomial, Monomial, or scalar.

    Returns:
        True if both represent the same polynomial.

    Raises:
        ValueError: If other is not a valid type.
    """
    if isinstance(other, (int, float, Fraction)):
        other_poly = Polynomial([Monomial({}, other)])
        return self.__eq__(other_poly)
    elif isinstance(other, Monomial):
        return self.__eq__(Polynomial([other]))
    elif isinstance(other, Polynomial):
        return self.all_monomials() == other.all_monomials()
    else:
        raise ValueError(
            "Can only compare a polynomial with an int, "
            "float, Fraction, Monomial, or another Polynomial."
        )

def subs(
    self,
    substitutions: int | float | Fraction | dict[int, int | float | Fraction],
) -> int | float | Fraction:
    """Evaluate the polynomial by substituting values for variables.

    Args:
        substitutions: A single value applied to all variables, or a
            dict mapping variable indices to values.

    Returns:
        The evaluated result.

    Raises:
        ValueError: If some variables are not given values.
    """
    if isinstance(substitutions, (int, float, Fraction)):
        substitutions = {
            i: Polynomial._rationalize_if_possible(substitutions)
            for i in set(self.variables())
        }
        return self.subs(substitutions)
    elif not isinstance(substitutions, dict):
        raise ValueError("The substitutions should be a dictionary.")
    if not self.variables().issubset(set(substitutions.keys())):
        raise ValueError("Some variables didn't receive their values.")

    ans = 0
    for m in self.all_monomials():
        ans += Polynomial._rationalize_if_possible(m.substitute(substitutions))
    return Polynomial._rationalize_if_possible(ans)

def _is_prime(n: int) -> bool:
    """Return ``True`` if *n* is a prime number.

    Examples:
        >>> _is_prime(7)
        True
        >>> _is_prime(10)
        False
    """
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def misras_gries(array: list[int], k: int = 2) -> dict[str, int] | None:
    """Find all elements appearing at least n/k times.

    Args:
        array: A list of integers.
        k: The frequency threshold divisor (default 2).

    Returns:
        A dict mapping element (as string) to its frequency, or None
        if no element meets the threshold.

    Examples:
        >>> misras_gries([1, 4, 4, 4, 5, 4, 4])
        {'4': 5}
        >>> misras_gries([0, 0, 0, 1, 1, 1, 1])
        {'1': 4}
        >>> misras_gries([0, 0, 0, 0, 1, 1, 1, 2, 2], 3)
        {'0': 4, '1': 3}
    """
    keys: dict[str, int] = {}
    for item in array:
        val = str(item)
        if val in keys:
            keys[val] += 1
        elif len(keys) < k - 1:
            keys[val] = 1
        else:
            for key in list(keys):
                keys[key] -= 1
                if keys[key] == 0:
                    del keys[key]

    suspects = keys.keys()
    frequencies: dict[str, int] = {}
    for suspect in suspects:
        freq = _count_frequency(array, int(suspect))
        if freq >= len(array) / k:
            frequencies[suspect] = freq

    return frequencies if frequencies else None

def unweighted(cls, adj: dict[str, list[str]], directed: bool = True) -> Graph:
    """Create a graph from an unweighted adjacency list.

    Args:
        adj: Mapping of node to list of neighbors.
        directed: Whether edges are one-directional.

    Returns:
        A Graph with all edge weights set to 1.

    Examples:
        >>> g = Graph.unweighted({"a": ["b", "c"], "b": ["c"]})
        >>> g.adj["b"]
        {'c': 1}
    """
    weighted = {
        node: {neighbor: 1 for neighbor in neighbors}
        for node, neighbors in adj.items()
    }
    return cls(adj=weighted, directed=directed)

def add_edge(self, source: str, target: str, weight: float = 1) -> None:
    """Add an edge to the graph.

    For undirected graphs, the reverse edge is also added.

    Args:
        source: Source node.
        target: Target node.
        weight: Edge weight (default 1).

    Examples:
        >>> g = Graph()
        >>> g.add_edge("a", "b", 5)
        >>> g.adj["a"]["b"]
        5
    """
    if source not in self.adj:
        self.adj[source] = {}
    self.adj[source][target] = weight
    if not self.directed:
        if target not in self.adj:
            self.adj[target] = {}
        self.adj[target][source] = weight

def __init__(self) -> None:
    """Initialize the randomized set."""
    self.nums: list[int] = []
    self.idxs: dict[int, int] = {}

def is_valid_sudoku(board: list[list[str]]) -> bool:
    """Check whether a Sudoku board configuration is valid.

    Args:
        board: 9x9 grid where empty cells are represented by '.'.

    Returns:
        True if the board is valid, False otherwise.

    Examples:
        >>> is_valid_sudoku([['.' for _ in range(9)] for _ in range(9)])
        True
    """
    seen: list[tuple[str, ...]] = []
    for i, row in enumerate(board):
        for j, cell in enumerate(row):
            if cell != ".":
                seen += [(cell, j), (i, cell), (i // 3, j // 3, cell)]
    return len(seen) == len(set(seen))

def __eq__(self, other: object) -> bool:
    if not isinstance(other, Node):
        return NotImplemented
    return self.frequency == other.frequency

def get_bit(self, buff_limit: int = 8) -> str | int:
    """Read a single bit from the buffer.

    Args:
        buff_limit: Minimum buffer size before loading.

    Returns:
        A '0' or '1' character, or -1 if at end of file.
    """
    if self._load_byte(buff_limit):
        return self.buffer.pop(0)
    return -1

def get_byte(self) -> str | int:
    """Read eight bits from the buffer.

    Returns:
        An 8-character binary string, or -1 if at end of file.
    """
    if self._load_byte():
        byte_list = self.buffer[:8]
        self.buffer = self.buffer[8:]
        return "".join(byte_list)
    return -1

def close(self) -> None:
    """Flush remaining bits with padding and finalize the file."""
    additional_bits = 8 - len(self.buffer)
    if additional_bits != 8:
        self.write_bits("0" * additional_bits)
        self._save_information_about_additional_bits(additional_bits)

def _go_through_tree_and_create_codes(
    tree: Node, code: str, dict_codes: dict[int, str]
) -> None:
    """Recursively traverse the tree to build code mappings.

    Args:
        tree: The current node being visited.
        code: The accumulated bit string for this path.
        dict_codes: The output dict to populate.
    """
    if tree.sign is not None:
        dict_codes[tree.sign] = code

    if tree.left:
        HuffmanCoding._go_through_tree_and_create_codes(
            tree.left, code + "0", dict_codes
        )

    if tree.right:
        HuffmanCoding._go_through_tree_and_create_codes(
            tree.right, code + "1", dict_codes
        )

def _get_code_tree(node: Node) -> None:
    nonlocal tree_code
    if node.sign is not None:
        signs.append(node.sign)
    if node.left:
        tree_code += "0"
        _get_code_tree(node.left)
    if node.right:
        tree_code += "1"
        _get_code_tree(node.right)

def gale_shapley(
    men: dict[str, list[str]],
    women: dict[str, list[str]],
) -> dict[str, str]:
    """Find a stable matching between men and women.

    Args:
        men: Mapping of each man to his preference list of women
            (highest to lowest).
        women: Mapping of each woman to her preference list of men
            (highest to lowest).

    Returns:
        A dict mapping each man to his matched woman.

    Examples:
        >>> men = {"M1": ["W1", "W2"], "M2": ["W1", "W2"]}
        >>> women = {"W1": ["M2", "M1"], "W2": ["M1", "M2"]}
        >>> sorted(gale_shapley(men, women).items())
        [('M1', 'W2'), ('M2', 'W1')]
    """
    men_available: list[str] = list(men.keys())
    married: dict[str, str] = {}
    proposal_counts: dict[str, int] = {man: 0 for man in men}

    while men_available:
        man = men_available.pop(0)
        woman = men[man][proposal_counts[man]]
        proposal_counts[man] += 1

        if woman not in married:
            married[woman] = man
        else:
            current_partner = married[woman]
            if women[woman].index(man) < women[woman].index(current_partner):
                married[woman] = man
                men_available.append(current_partner)
            else:
                men_available.append(man)

    return {man: woman for woman, man in married.items()}

def _insertion_sort(array: list[int]) -> list[int]:
    """Sort *array* in-place using insertion sort and return it."""
    for i in range(1, len(array)):
        key = array[i]
        j = i - 1
        while j >= 0 and array[j] > key:
            array[j + 1] = array[j]
            j -= 1
        array[j + 1] = key
    return array

def _quick_sort_recursive(array: list[int], first: int, last: int) -> None:
    """Recursively sort *array[first..last]* in-place."""
    if first < last:
        pivot = _partition(array, first, last)
        _quick_sort_recursive(array, first, pivot - 1)
        _quick_sort_recursive(array, pivot + 1, last)

def _stooge_sort(array: list[int], low: int, high: int) -> None:
    """Recursively sort *array[low..high]* using stooge sort."""
    if low >= high:
        return

    if array[low] > array[high]:
        array[low], array[high] = array[high], array[low]

    if high - low + 1 > 2:
        third = (high - low + 1) // 3
        _stooge_sort(array, low, high - third)
        _stooge_sort(array, low + third, high)
        _stooge_sort(array, low, high - third)

def _is_sorted(array: list[int]) -> bool:
    """Return True if *array* is in non-decreasing order."""
    return all(
        array[i] <= array[i + 1] for i in range(len(array) - 1)
    )

def _max_heapify(array: list[int], end: int) -> None:
    """Build a max-heap on *array[0..end]* and swap the root to *end*."""
    last_parent = (end - 1) // 2

    for parent in range(last_parent, -1, -1):
        current = parent
        while current <= last_parent:
            child = 2 * current + 1
            if child + 1 <= end and array[child] < array[child + 1]:
                child += 1
            if array[child] > array[current]:
                array[current], array[child] = array[child], array[current]
                current = child
            else:
                break

    array[0], array[end] = array[end], array[0]

def _min_heapify(array: list[int], start: int) -> None:
    """Build a min-heap on *array[start..]* and place the minimum at *start*."""
    end = len(array) - 1
    last_parent = (end - start - 1) // 2

    for parent in range(last_parent, -1, -1):
        current = parent
        while current <= last_parent:
            child = 2 * current + 1
            if (
                child + 1 <= end - start
                and array[child + start] > array[child + 1 + start]
            ):
                child += 1
            if array[child + start] < array[current + start]:
                array[current + start], array[child + start] = (
                    array[child + start],
                    array[current + start],
                )
                current = child
            else:
                break

def _compare(array: list[int], reverse: bool) -> list[int]:
    """Compare and swap elements across the two halves of *array*."""
    half = len(array) // 2
    for i in range(half):
        if reverse != (array[i] > array[i + half]):
            array[i], array[i + half] = array[i + half], array[i]
    return array

def has_next(self) -> bool:
    """Check if there are more elements.

    Returns:
        True if elements remain, False otherwise.
    """
    return bool(self.queue)

def can_swap_to_equal(s: str, t: str) -> bool:
    """Return True if swapping exactly one pair in *s* yields *t*."""
    if len(s) != len(t):
        return False
    diffs = [(a, b) for a, b in zip(s, t, strict=False) if a != b]
    return len(diffs) == 2 and diffs[0] == diffs[1][::-1]

def alphabet_board_path(target: str) -> str:
    """Return move string to spell *target* on the alphabet board."""
    moves: list[str] = []
    row, col = 0, 0
    for ch in target:
        idx = ord(ch) - ord("a")
        target_row, target_col = divmod(idx, 5)
        # Move up/left before down/right to avoid going off-board at 'z'
        if target_row < row:
            moves.append("U" * (row - target_row))
        if target_col < col:
            moves.append("L" * (col - target_col))
        if target_row > row:
            moves.append("D" * (target_row - row))
        if target_col > col:
            moves.append("R" * (target_col - col))
        moves.append("!")
        row, col = target_row, target_col
    return "".join(moves)

def is_rotated_v1(first: str, second: str) -> bool:
    """Check if second is a rotation of first using brute force comparison.

    Args:
        first: The original string.
        second: The string to check as a rotation.

    Returns:
        True if second is a rotation of first, False otherwise.

    Examples:
        >>> is_rotated_v1("hello", "llohe")
        True
    """
    if len(first) != len(second):
        return False
    if len(first) == 0:
        return True

    for offset in range(len(first)):
        if all(
            first[(offset + index) % len(first)] == second[index]
            for index in range(len(first))
        ):
            return True
    return False

def __init__(self, text: str, window_size: int) -> None:
    self.text = text
    self.hash = 0
    self.window_size = window_size

    for index in range(0, window_size):
        self.hash += (ord(self.text[index]) - ord("a") + 1) * (
            26 ** (window_size - index - 1)
        )

    self.window_start = 0
    self.window_end = window_size

def move_window(self) -> None:
    """Slide the hash window one position to the right."""
    if self.window_end <= len(self.text) - 1:
        self.hash -= (ord(self.text[self.window_start]) - ord("a") + 1) * 26 ** (
            self.window_size - 1
        )
        self.hash *= 26
        self.hash += ord(self.text[self.window_end]) - ord("a") + 1
        self.window_start += 1
        self.window_end += 1

def compute_z_array(s: str) -> list[int]:
    """Compute the Z-array for string *s* in O(n) time."""
    n = len(s)
    if n == 0:
        return []
    z = [0] * n
    z[0] = n
    left = right = 0
    for i in range(1, n):
        if i < right:
            z[i] = min(right - i, z[i - left])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > right:
            left, right = i, i + z[i]
    return z

def _build(square: list[str]) -> None:
    if len(square) == word_length:
        squares.append(square)
        return
    prefix = ""
    for row in range(len(square)):
        prefix += square[row][len(square)]
    for word in prefix_map[prefix]:
        _build(square + [word])

def is_one_edit(source: str, target: str) -> bool:
    """Check if two strings are exactly one edit apart using slicing.

    Args:
        source: The first string.
        target: The second string.

    Returns:
        True if the strings are exactly one edit apart, False otherwise.

    Examples:
        >>> is_one_edit("abc", "abd")
        True
    """
    if len(source) > len(target):
        return is_one_edit(target, source)
    if len(target) - len(source) > 1 or target == source:
        return False
    for index in range(len(source)):
        if source[index] != target[index]:
            return (
                source[index + 1 :] == target[index + 1 :]
                or source[index:] == target[index + 1 :]
            )
    return True

def is_one_edit2(source: str, target: str) -> bool:
    """Check if two strings are exactly one edit apart using modification.

    Args:
        source: The first string.
        target: The second string.

    Returns:
        True if the strings are exactly one edit apart, False otherwise.

    Examples:
        >>> is_one_edit2("abc", "abd")
        True
    """
    source_length, target_length = len(source), len(target)
    if source_length > target_length:
        return is_one_edit2(target, source)
    if len(target) - len(source) > 1 or target == source:
        return False
    for index in range(len(source)):
        if source[index] != target[index]:
            if source_length == target_length:
                source = source[:index] + target[index] + source[index + 1 :]
            else:
                source = source[:index] + target[index] + source[index:]
            break
    return source == target or source == target[:-1]

def _lcs(word1: str, word2: str, length1: int, length2: int) -> int:
    """Compute the length of the longest common subsequence recursively.

    Args:
        word1: The first word.
        word2: The second word.
        length1: Current length to consider in word1.
        length2: Current length to consider in word2.

    Returns:
        The length of the longest common subsequence.
    """
    if length1 == 0 or length2 == 0:
        return 0
    if word1[length1 - 1] == word2[length2 - 1]:
        return 1 + _lcs(word1, word2, length1 - 1, length2 - 1)
    return max(
        _lcs(word1, word2, length1 - 1, length2),
        _lcs(word1, word2, length1, length2 - 1),
    )

def min_distance_dp(word1: str, word2: str) -> int:
    """Find minimum deletions to make two words equal using dynamic programming.

    Args:
        word1: The first word.
        word2: The second word.

    Returns:
        The minimum number of deletion steps.

    Examples:
        >>> min_distance_dp("sea", "eat")
        2
    """
    rows, cols = len(word1) + 1, len(word2) + 1
    table = [[0 for _ in range(cols)] for _ in range(rows)]

    if rows == cols:
        for index in range(1, rows):
            table[index][0], table[0][index] = index, index
    else:
        for index in range(rows):
            table[index][0] = index
        for index in range(cols):
            table[0][index] = index

    for row in range(1, rows):
        for col in range(1, cols):
            if word1[row - 1] == word2[col - 1]:
                table[row][col] = table[row - 1][col - 1]
            else:
                table[row][col] = min(table[row - 1][col], table[row][col - 1]) + 1

    return table[len(word1)][len(word2)]

def push(self, item: int) -> None:
    """Push an item while maintaining sorted order.

    Args:
        item: The value to push.
    """
    temp_stack = OrderedStack()
    if self.is_empty() or item > self.peek():
        self._push_direct(item)
    else:
        while item < self.peek() and not self.is_empty():
            temp_stack._push_direct(self.pop())
        self._push_direct(item)
        while not temp_stack.is_empty():
            self._push_direct(temp_stack.pop())

def pop(self) -> int:
    """Remove and return the top element.

    Returns:
        The top (largest) element.

    Raises:
        IndexError: If the stack is empty.
    """
    if self.is_empty():
        raise IndexError("Stack is empty")
    return self.items.pop()

def size(self) -> int:
    """Return the number of elements in the stack.

    Returns:
        The stack size.
    """
    return len(self.items)

def simplify_path(path: str) -> str:
    """Simplify a Unix-style absolute path.

    Args:
        path: An absolute file path string.

    Returns:
        The simplified canonical path.

    Examples:
        >>> simplify_path("/home/")
        '/home'
        >>> simplify_path("/a/./b/../../c/")
        '/c'
    """
    skip = {"..", ".", ""}
    stack: list[str] = []
    tokens = path.split("/")
    for token in tokens:
        if token == "..":
            if stack:
                stack.pop()
        elif token not in skip:
            stack.append(token)
    return "/" + "/".join(stack)

